describe('Notification Dismissal', () => {
  beforeEach(() => {
    cy.visit('/notifications');
  });

  it('should successfully dismiss a notification by clicking the close button', () => {
    // Verify notification is displayed
    cy.get('[data-testid="notification-list"]').should('be.visible');
    cy.get('[data-testid="notification-item"]').should('contain', 'New message');

    // Click the close button
    cy.get('[data-testid="notification-close-btn"]').click();

    // Verify notification is removed from the list
    cy.get('[data-testid="notification-list"]').should('contain', 'New message');

    // Verify notification count is decremented
    cy.get('[data-testid="notification-count"]').should('contain', '1');

    // Verify notification is removed from the DOM
    cy.get('[data-testid="notification-item"]').should('not.exist');
  });

  it('should not dismiss a notification when close button is disabled', () => {
    // Verify notification is displayed
    cy.get('[data-testid="notification-list"]').should('be.visible');
    cy.get('[data-testid="notification-item"]').should('contain', 'System update');

    // Click the close button
    cy.get('[data-testid="notification-close-btn"]').click();

    // Verify notification remains visible (close button is disabled)
    cy.get('[data-testid="notification-item"]').should('be.visible');

    // Verify notification count remains unchanged
    cy.get('[data-testid="notification-count"]').should('contain', '1');

    // Verify close button is disabled
    cy.get('[data-testid="notification-close-btn"]').should('have.attr', 'disabled');
  });
});
